]===(int)$group['id']&&$item['active']) as$option):?><label><input type="<?= $group['selection_type']==='single'?'radio':'checkbox' ?>" name="service_group_<?= (int)$p['id'] ?>_<?= (int)$group['id'] ?>" value="<?= (int)$option['id'] ?>" data-service-option-product="<?= (int)$p['id'] ?>"> <?= e($option['name']) ?><?= $option['price_cents']?' (+'.$money((int)$option['price_cents']).')':'' ?></label><?php endforeach;?></fieldset><?php endforeach;?></details><?php endforeach;?></fieldset><button class="botao primario completo" type="submit">Enviar para cozinha</button><output id="serviceOrderResult" class="aviso" hidden></output></form></article></div>
