()) ?>"><input type="hidden" name="return_to" value="<?= e($returnPath) ?>"><input type="hidden" name="id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="status" value="<?= e($nextStatus) ?>"><button class="botao primario completo"><?= e($buttonLabels[$nextStatus]) ?></button></form><?php endif;?></article><?php endforeach;?></div><?php endif;?></section><?php endif;?></main><script src="/assets/admin-ui.js?v=20260903-review1" defer></script></body></html>

